TARGET_ANSWERS = 'ABCDBCDACB'
def make(i, row):
    tag, prompt, opts, answer, reason = row
    target = TARGET_ANSWERS[i - 1]
    distractors = [t for t in opts if t != answer]
    opts = distractors[:ord(target) - 65] + [answer] + distractors[ord(target) - 65:]
    options = [{'id': chr(65+j), 'text': t} for j, t in enumerate(opts)]
    aid = target
    steps = [f'讀題定位：圈出「{tag}」以及地層上下、化石分布、岩性、構造或年代方法。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合地層與化石記錄地球歷史的證據邏輯。', '排除誘答：分清相對與絕對年代、岩性與化石證據、原始順序與後來變形，不把單一線索過度延伸。', '最後回查：確認地層是否連續、是否變形、資料是否可比及結論不確定性。']
    return {'id': f'question-science-content-hb-iv-1-{i}', 'subject': 'science', 'type': 'single-choice', 'prompt': prompt, 'options': options, 'knowledgeIds': ['kg-science-content-hb-iv-1'], 'difficulty': 'medium', 'answer': {'value': aid, 'explanation': reason}, 'provenance': {'origin': 'original', 'license': 'All rights reserved', 'sourceUrl': URL, 'sourceLocator': '公立國中段考自然科；研究疊積律、化石、標準化石、岩性、地層變形、不整合與相對年代判讀的能力方向。', 'authoringNote': '依官方課綱 KG 與公立國中公開試題能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}, 'reviewStatus': 'draft', 'updatedAt': '2026-09-08', 'lessonId': 'lesson-science-content-hb-iv-1', 'examPatternRefs': [{'url': URL, 'title': '公立國中段考自然科；僅研究題型與能力方向，未複製原題。', 'year': '114', 'subject': 'science', 'locator': '岩性與化石記錄地球歷史', 'observedPattern': '能力方向研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'}], 'solutionStrategy': '先用疊積律與構造關係建立地層先後，再用岩性、化石與標準化石對比，最後區分相對年代、絕對年代與資料缺口。', 'solutionSteps': steps}

for i, row in enumerate(DATA, 1):
    (OUT / f'question-science-content-hb-iv-1-{i}.json').write_text(json.dumps(make(i, row), ensure_ascii=False, indent=2) + '\n')
